Write a Python script that reads the input JSON from the file 'input.json' in the current working directory, computes the tax output, and prints ONLY the output JSON to stdout. You have access to the Python standard library only.

IMPORTANT -- this overrides the output-format instruction in the system prompt above. For this task do NOT reply with the tax JSON itself. Reply with the Python script, wrapped in a ```python code fence. The JSON schema in the system prompt describes what your script must PRINT, not what you should reply with.

```python
import json
import sys
from datetime import date

with open("input.json", "r", encoding="utf-8") as f:
    data = json.load(f)


def num(value):
    return float(value) if isinstance(value, (int, float)) else 0.0


def val(obj, key):
    return num(obj.get(key, 0))


def add_years(d, years):
    try:
        return d.replace(year=d.year + years)
    except ValueError:
        return d.replace(year=d.year + years, day=28)


def held_longer(purchase, sale, years):
    return sale > add_years(purchase, years)


def slab_tax(income, regime, age):
    income = max(0.0, income)

    if regime == "new":
        brackets = [
            (0, 400000, 0.00),
            (400000, 800000, 0.05),
            (800000, 1200000, 0.10),
            (1200000, 1600000, 0.15),
            (1600000, 2000000, 0.20),
            (2000000, 2400000, 0.25),
            (2400000, float("inf"), 0.30),
        ]
    elif age >= 80:
        brackets = [
            (0, 500000, 0.00),
            (500000, 1000000, 0.20),
            (1000000, float("inf"), 0.30),
        ]
    elif age >= 60:
        brackets = [
            (0, 300000, 0.00),
            (300000, 500000, 0.05),
            (500000, 1000000, 0.20),
            (1000000, float("inf"), 0.30),
        ]
    else:
        brackets = [
            (0, 250000, 0.00),
            (250000, 500000, 0.05),
            (500000, 1000000, 0.20),
            (1000000, float("inf"), 0.30),
        ]

    tax = 0.0
    for lower, upper, rate in brackets:
        if income > lower:
            tax += (min(income, upper) - lower) * rate
        if income <= upper:
            break
    return tax


def basic_exemption(regime, age):
    if regime == "new":
        return 400000.0
    if age >= 80:
        return 500000.0
    if age >= 60:
        return 300000.0
    return 250000.0


def eligible_loss(loss):
    try:
        year = int(str(loss.get("Financial Year", ""))[:4])
        return 0 <= 2025 - year <= 8
    except (TypeError, ValueError):
        return False


def apply_loss(gain, loss_pool):
    used = min(max(0.0, gain), loss_pool)
    return gain - used, loss_pool - used


regime = data.get("Tax Regime", "new")
age = int(data.get("Age", 0))
salary = data.get("Gross Salary", {})

gross_salary = sum(num(value) for value in salary.values())
basic_da = val(salary, "Basic Salary") + val(salary, "Dearness Allowance")

hra_exemption = 0.0
lta_exemption = 0.0
entertainment_deduction = 0.0
professional_tax_deduction = 0.0

if regime == "old":
    hra_exemption = max(
        0.0,
        min(
            val(salary, "HRA"),
            val(data, "Actual Rent Paid") - 0.10 * basic_da,
            (0.50 if data.get("City") == "metro" else 0.40) * basic_da,
        ),
    )
    lta_exemption = min(
        val(salary, "LTA"),
        val(data, "LTA Travel Expenses Claimed"),
    )
    standard_deduction = 50000.0

    if data.get("Employment Type") == "government":
        entertainment_deduction = min(
            val(salary, "Entertainment Allowance"),
            5000.0,
            0.20 * val(salary, "Basic Salary"),
        )

    professional_tax_deduction = val(data, "Professional Tax")
else:
    standard_deduction = 75000.0

standard_deduction = min(
    standard_deduction,
    max(0.0, gross_salary - hra_exemption - lta_exemption),
)

net_salary = max(
    0.0,
    gross_salary
    - hra_exemption
    - lta_exemption
    - standard_deduction
    - entertainment_deduction
    - professional_tax_deduction,
)

cg = {
    "st111a": 0.0,
    "st_other": {
        "Bonds": 0.0,
        "Debentures": 0.0,
        "G-Secs": 0.0,
        "Mutual Funds": 0.0,
    },
    "st_extra": 0.0,
    "lt112a": 0.0,
    "lt_non_equity": {
        "Bonds": 0.0,
        "Debentures": 0.0,
        "G-Secs": 0.0,
        "Mutual Funds": 0.0,
    },
    "lt_other": 0.0,
}
current_loss = {"ST": 0.0, "LT": 0.0}


def record_gain(gain, long_term, preferential_equity=False, category=None):
    if gain < 0:
        current_loss["LT" if long_term else "ST"] += -gain
        return
    if gain == 0:
        return

    if long_term:
        if preferential_equity:
            cg["lt112a"] += gain
        elif category is not None:
            cg["lt_non_equity"][category] += gain
        else:
            cg["lt_other"] += gain
    else:
        if preferential_equity:
            cg["st111a"] += gain
        elif category is not None:
            cg["st_other"][category] += gain
        else:
            cg["st_extra"] += gain


for transaction in data.get("Stock Sale Transactions", []):
    purchase = date.fromisoformat(transaction["Purchase Date"])
    sale = date.fromisoformat(transaction["Sale Date"])
    long_term = held_longer(purchase, sale, 1)

    quantity = val(transaction, "Quantity")
    sale_price = val(transaction, "Sale Price")
    cost_price = val(transaction, "Cost Price")
    acquisition_cost = cost_price * quantity

    fmv = val(transaction, "FMV as of 31 Jan 2018")
    if long_term and purchase < date(2018, 2, 1) and fmv > 0:
        acquisition_cost = (
            max(cost_price, min(fmv, sale_price)) * quantity
        )

    # Brokerage is deductible; STT is not deductible under section 48.
    gain = (
        sale_price * quantity
        - acquisition_cost
        - val(transaction, "Brokerage")
    )
    record_gain(
        gain,
        long_term,
        preferential_equity=val(transaction, "STT") > 0,
    )

equity_mf_types = {"equity", "elss", "hybrid-equity"}

for transaction in data.get("Mutual Fund Transactions", []):
    purchase = date.fromisoformat(transaction["Purchase Date"])
    sale = date.fromisoformat(transaction["Sale Date"])
    mf_type = str(transaction.get("Type", "")).lower()
    gain = val(transaction, "Sale Value") - val(transaction, "Purchase Value")

    if mf_type in equity_mf_types:
        record_gain(
            gain,
            held_longer(purchase, sale, 1),
            preferential_equity=True,
        )
    else:
        deemed_short = (
            mf_type == "debt" and purchase >= date(2023, 4, 1)
        )
        required_years = 1 if mf_type == "gold-etf" else 2
        long_term = (
            not deemed_short
            and held_longer(purchase, sale, required_years)
        )
        record_gain(gain, long_term, category="Mutual Funds")

for asset_name in ("Bonds", "Debentures", "G-Secs"):
    asset = data.get(asset_name, {})
    gain = val(asset, "Sale Amount") - val(asset, "Purchase Amount")
    long_term = val(asset, "Held for duration in years") > 1
    record_gain(gain, long_term, category=asset_name)

vehicle = data.get("Privately Owned Vehicle", {})
vehicle_gain = val(vehicle, "Sale Amount") - val(vehicle, "Purchase Amount")
record_gain(
    vehicle_gain,
    val(vehicle, "Held for duration in years") > 2,
)

st_loss_pool = current_loss["ST"] + sum(
    val(loss, "Loss Amount")
    for loss in data.get("Short Term Capital Loss", [])
    if eligible_loss(loss)
)
lt_loss_pool = current_loss["LT"] + sum(
    val(loss, "Loss Amount")
    for loss in data.get("Long Term Capital Loss", [])
    if eligible_loss(loss)
)

cg["st111a"], st_loss_pool = apply_loss(cg["st111a"], st_loss_pool)
cg["st_extra"], st_loss_pool = apply_loss(cg["st_extra"], st_loss_pool)

for key in cg["st_other"]:
    cg["st_other"][key], st_loss_pool = apply_loss(
        cg["st_other"][key], st_loss_pool
    )

for key in cg["lt_non_equity"]:
    cg["lt_non_equity"][key], lt_loss_pool = apply_loss(
        cg["lt_non_equity"][key], lt_loss_pool
    )

cg["lt_other"], lt_loss_pool = apply_loss(cg["lt_other"], lt_loss_pool)
cg["lt112a"], lt_loss_pool = apply_loss(cg["lt112a"], lt_loss_pool)

if st_loss_pool > 0:
    cg["lt_other"], st_loss_pool = apply_loss(
        cg["lt_other"], st_loss_pool
    )
    for key in cg["lt_non_equity"]:
        cg["lt_non_equity"][key], st_loss_pool = apply_loss(
            cg["lt_non_equity"][key], st_loss_pool
        )
    cg["lt112a"], st_loss_pool = apply_loss(
        cg["lt112a"], st_loss_pool
    )

stcg_other_total = sum(cg["st_other"].values()) + cg["st_extra"]
ltcg_non_equity_total = sum(cg["lt_non_equity"].values())

savings_interest = val(data, "Savings Bank Interest")
deposit_interest = val(data, "Deposit Interest")
other_interest = val(data, "Other Interest")
epf_taxable_interest = val(data, "EPF Taxable Interest")

other_sources_total = (
    savings_interest
    + deposit_interest
    + other_interest
    + epf_taxable_interest
)

gross_total_income = (
    net_salary
    + cg["st111a"]
    + stcg_other_total
    + cg["lt112a"]
    + ltcg_non_equity_total
    + cg["lt_other"]
    + other_sources_total
)

deductions = {
    "80C": 0.0,
    "80CCC": 0.0,
    "80CCD(1)": 0.0,
    "80CCD(1B)": 0.0,
    "80CCD(2)": 0.0,
    "80D": 0.0,
    "80E": 0.0,
    "80G": 0.0,
    "80TTA": 0.0,
    "80TTB": 0.0,
}

nps = data.get("NPS", {})
employer_nps = val(nps, "Tier-1 Employer Contribution")

if regime == "new":
    deductions["80CCD(2)"] = min(employer_nps, 0.14 * basic_da)
else:
    epf = data.get("EPF", {})
    employee_epf = epf.get("Employee Contribution", {})

    section_80c_investments = (
        val(data, "PPF")
        + val(data, "ELSS")
        + val(data, "NSC")
        + val(data, "Sukanya Samriddhi Yojana")
        + val(data, "SCSS")
        + val(employee_epf, "Deducted from Salary")
        + val(employee_epf, "Voluntary")
    )

    pension = data.get("Pension Scheme Premium", {})
    pension_years = max(
        1, int(pension.get("Number of Years Paid", 1) or 1)
    )
    pension_amount = val(pension, "Amount") / pension_years

    self_nps = val(nps, "Tier-1 Self Contribution")
    deductions["80CCD(1B)"] = min(self_nps, 50000.0)
    nps_for_combined_limit = self_nps - deductions["80CCD(1B)"]

    deductions["80C"] = min(section_80c_investments, 150000.0)
    remaining_limit = 150000.0 - deductions["80C"]

    deductions["80CCC"] = min(pension_amount, remaining_limit)
    remaining_limit -= deductions["80CCC"]

    deductions["80CCD(1)"] = min(
        nps_for_combined_limit,
        0.10 * basic_da,
        remaining_limit,
    )

    employer_rate = (
        0.14 if data.get("Employment Type") == "government" else 0.10
    )
    deductions["80CCD(2)"] = min(
        employer_nps, employer_rate * basic_da
    )

    self_premium = 0.0
    parent_premium = 0.0
    self_senior = False
    parent_senior = False

    for policy in data.get("Health Insurance", []):
        if policy.get("Paid By") != "self":
            continue

        purpose = str(policy.get("Payment Purpose", "")).lower()
        mode = str(policy.get("Payment Mode", "")).lower()
        if mode == "cash" and "preventive" not in purpose:
            continue

        years = max(
            1, int(policy.get("Number of Years Paid", 1) or 1)
        )
        eligible_amount = val(policy, "Amount") / years
        beneficiary = str(policy.get("Beneficiary", "")).lower()
        is_parent = beneficiary in {
            "parent", "parents", "father", "mother"
        }
        is_senior = int(policy.get("Beneficiary Age", 0)) >= 60

        if is_parent:
            parent_premium += eligible_amount
            parent_senior = parent_senior or is_senior
        else:
            self_premium += eligible_amount
            self_senior = self_senior or is_senior

    deductions["80D"] = (
        min(self_premium, 50000.0 if self_senior else 25000.0)
        + min(parent_premium, 50000.0 if parent_senior else 25000.0)
    )

    education_loan = data.get("Education Loan Interest", {})
    repayment_year = int(education_loan.get("Year of Repayment", 0))
    if 1 <= repayment_year <= 8:
        deductions["80E"] = val(education_loan, "Interest Paid")

    for donation in data.get("Donations", []):
        donation_amount = val(donation, "Amount")
        mode = str(donation.get("Mode", "")).lower()

        if mode == "cash" and donation_amount > 2000:
            continue

        scheme = str(donation.get("Scheme Name", "")).lower()
        fraction = (
            1.0
            if "pm cares" in scheme or "national defence" in scheme
            else 0.50
        )
        deductions["80G"] += donation_amount * fraction

    if age >= 60:
        deductions["80TTB"] = min(
            savings_interest + deposit_interest, 50000.0
        )
    else:
        deductions["80TTA"] = min(savings_interest, 10000.0)

total_deductions = sum(deductions.values())
total_taxable_income = max(
    0.0, gross_total_income - total_deductions
)

ordinary_income = max(
    0.0,
    net_salary + other_sources_total - total_deductions,
)

tax_at_slab = slab_tax(ordinary_income, regime, age)
tax_stcg_other = max(
    0.0,
    slab_tax(
        ordinary_income + stcg_other_total,
        regime,
        age,
    ) - tax_at_slab,
)

unused_basic = max(
    0.0,
    basic_exemption(regime, age)
    - ordinary_income
    - stcg_other_total,
)

used_basic = min(cg["st111a"], unused_basic)
stcg_111a_base = cg["st111a"] - used_basic
unused_basic -= used_basic
tax_stcg_111a = 0.20 * stcg_111a_base

used_basic = min(cg["lt112a"], unused_basic)
ltcg_112a_after_basic = cg["lt112a"] - used_basic
unused_basic -= used_basic
tax_ltcg_112a = 0.125 * max(
    0.0, ltcg_112a_after_basic - 125000.0
)

used_basic = min(ltcg_non_equity_total, unused_basic)
ltcg_non_equity_base = ltcg_non_equity_total - used_basic
unused_basic -= used_basic
tax_ltcg_non_equity = 0.125 * ltcg_non_equity_base

used_basic = min(cg["lt_other"], unused_basic)
ltcg_other_base = cg["lt_other"] - used_basic
tax_ltcg_other = 0.20 * ltcg_other_base

total_tax_before_rebate = (
    tax_at_slab
    + tax_stcg_111a
    + tax_stcg_other
    + tax_ltcg_112a
    + tax_ltcg_non_equity
    + tax_ltcg_other
)

rebate = 0.0

if regime == "new" and total_taxable_income <= 1200000:
    rebate = min(
        60000.0,
        max(0.0, total_tax_before_rebate - tax_ltcg_112a),
    )
elif regime == "old" and total_taxable_income <= 500000:
    rebate = min(12500.0, total_tax_before_rebate)

tax_after_rebate = max(0.0, total_tax_before_rebate - rebate)

if regime == "new" and total_taxable_income > 1200000:
    excess_income = total_taxable_income - 1200000
    if tax_after_rebate > excess_income:
        marginal_relief = tax_after_rebate - excess_income
        rebate += marginal_relief
        tax_after_rebate = excess_income

surcharge_rate = 0.0
if total_taxable_income > 50000000:
    surcharge_rate = 0.25 if regime == "new" else 0.37
elif total_taxable_income > 20000000:
    surcharge_rate = 0.25
elif total_taxable_income > 10000000:
    surcharge_rate = 0.15
elif total_taxable_income > 5000000:
    surcharge_rate = 0.10

surcharge = tax_after_rebate * surcharge_rate
cess = 0.04 * (tax_after_rebate + surcharge)
total_tax_liability = tax_after_rebate + surcharge + cess

tds = val(data, "TDS")
net_tax = total_tax_liability - tds

output = {
    "Under Head Salaries": {
        "Gross Salary": gross_salary,
        "Exemptions": {
            "Section 10(13A)": hra_exemption,
            "Section 10(5)": lta_exemption,
        },
        "Section 16(ia)": standard_deduction,
        "Section 16(ii)": entertainment_deduction,
        "Section 16(iii)": professional_tax_deduction,
        "Net Salary": net_salary,
    },
    "Capital Gains": {
        "STCG (Section 111A)": cg["st111a"],
        "STCG (Other)": {
            "Bonds": cg["st_other"]["Bonds"],
            "Debentures": cg["st_other"]["Debentures"],
            "G-Secs": cg["st_other"]["G-Secs"],
            "Mutual Funds": cg["st_other"]["Mutual Funds"],
            "Total": stcg_other_total,
        },
        "LTCG (Section 112A)": cg["lt112a"],
        "LTCG (Non-Equity)": {
            "Bonds": cg["lt_non_equity"]["Bonds"],
            "Debentures": cg["lt_non_equity"]["Debentures"],
            "G-Secs": cg["lt_non_equity"]["G-Secs"],
            "Mutual Funds": cg["lt_non_equity"]["Mutual Funds"],
            "Total": ltcg_non_equity_total,
        },
        "LTCG (Other)": cg["lt_other"],
    },
    "Income from Other Sources": {
        "Savings Bank Interest": savings_interest,
        "Deposit Interest": deposit_interest,
        "Other Interest": other_interest,
        "EPF Taxable Interest": epf_taxable_interest,
    },
    "Gross Total Income": gross_total_income,
    "Deductions": {
        **deductions,
        "Total Deductions": total_deductions,
    },
    "Total Taxable Income": total_taxable_income,
    "Tax Computation": {
        "Tax at Slab Rates": tax_at_slab,
        "Tax on STCG (Section 111A)": tax_stcg_111a,
        "Tax on STCG (Other)": tax_stcg_other,
        "Tax on LTCG (Section 112A)": tax_ltcg_112a,
        "Tax on LTCG (Non-Equity)": tax_ltcg_non_equity,
        "Tax on LTCG (Other)": tax_ltcg_other,
        "Total Tax Before Rebate": total_tax_before_rebate,
        "Less: Rebate under Section 87A": rebate,
        "Tax After Rebate": tax_after_rebate,
        "Surcharge": surcharge,
        "Health and Education Cess": cess,
        "Total Tax Liability": total_tax_liability,
        "Less: TDS": tds,
        "Net Tax Payable / Refund": net_tax,
    },
}


def clean_numbers(value):
    if isinstance(value, dict):
        return {
            key: clean_numbers(item)
            for key, item in value.items()
        }
    if isinstance(value, float):
        if abs(value) < 1e-9:
            return 0
        if abs(value - round(value)) < 1e-9:
            return int(round(value))
        return round(value, 2)
    return value


json.dump(clean_numbers(output), sys.stdout, indent=4)
