import json
from datetime import date

with open("input.json", "r", encoding="utf-8") as f:
    data = json.load(f)


def parse_date(value):
    return date.fromisoformat(value)


def clean(value):
    if isinstance(value, dict):
        return {k: clean(v) for k, v in value.items()}
    if isinstance(value, float):
        if abs(value - round(value)) < 1e-7:
            return int(round(value))
        return round(value, 2)
    return value


regime = data["Tax Regime"]
old_regime = regime == "old"
salary_parts = data["Gross Salary"]
gross_salary = sum(salary_parts.values())
basic = salary_parts["Basic Salary"]
da = salary_parts["Dearness Allowance"]
salary_for_limits = basic + da

# Salary exemptions and deductions
if old_regime:
    hra_exemption = min(
        salary_parts["HRA"],
        max(0, data["Actual Rent Paid"] - 0.10 * salary_for_limits),
        (0.50 if data["City"] == "metro" else 0.40) * salary_for_limits,
    )
    lta_exemption = min(
        salary_parts["LTA"], data["LTA Travel Expenses Claimed"]
    )
    standard_deduction = 50000
    entertainment_deduction = (
        min(5000, 0.20 * basic, salary_parts["Entertainment Allowance"])
        if data["Employment Type"] == "government"
        else 0
    )
    professional_tax = data["Professional Tax"]
else:
    hra_exemption = 0
    lta_exemption = 0
    standard_deduction = 75000
    entertainment_deduction = 0
    professional_tax = 0

net_salary = (
    gross_salary
    - hra_exemption
    - lta_exemption
    - standard_deduction
    - entertainment_deduction
    - professional_tax
)

# Capital gains before loss set-off; these raw figures are reported in the output.
stcg_111a = 0.0
ltcg_112a = 0.0
ltcg_other = 0.0
stcg_other = {"Bonds": 0.0, "Debentures": 0.0, "G-Secs": 0.0, "Mutual Funds": 0.0}
ltcg_non_equity = {"Bonds": 0.0, "Debentures": 0.0, "G-Secs": 0.0, "Mutual Funds": 0.0}

for tx in data["Stock Sale Transactions"]:
    quantity = tx["Quantity"]
    proceeds = tx["Sale Price"] * quantity
    acquisition_cost = tx["Cost Price"] * quantity
    purchase_date = parse_date(tx["Purchase Date"])
    sale_date = parse_date(tx["Sale Date"])
    long_term = (sale_date - purchase_date).days > 365

    # STT is not deductible while computing capital gains; brokerage is deductible.
    if long_term and tx["STT"] > 0 and purchase_date < date(2018, 2, 1):
        grandfathered_cost_per_share = max(
            tx["Cost Price"],
            min(tx["FMV as of 31 Jan 2018"], tx["Sale Price"]),
        )
        acquisition_cost = grandfathered_cost_per_share * quantity

    gain = proceeds - acquisition_cost - tx["Brokerage"]
    if tx["STT"] > 0:
        if long_term:
            ltcg_112a += gain
        else:
            stcg_111a += gain
    elif long_term:
        ltcg_other += gain

for tx in data["Mutual Fund Transactions"]:
    gain = tx["Sale Value"] - tx["Purchase Value"]
    purchase_date = parse_date(tx["Purchase Date"])
    sale_date = parse_date(tx["Sale Date"])
    holding_days = (sale_date - purchase_date).days
    fund_type = tx["Type"].lower()
    equity_types = {"equity", "elss", "hybrid-equity"}

    if fund_type in equity_types:
        if holding_days > 365:
            ltcg_112a += gain
        else:
            stcg_111a += gain
    else:
        # Debt funds acquired on or after 1 April 2023 fall under section 50AA.
        deemed_short_term = fund_type == "debt" and purchase_date >= date(2023, 4, 1)
        if deemed_short_term or holding_days <= 730:
            stcg_other["Mutual Funds"] += gain
        else:
            ltcg_non_equity["Mutual Funds"] += gain

for asset in ("Bonds", "Debentures", "G-Secs"):
    details = data[asset]
    if details["Sale Amount"] or details["Purchase Amount"]:
        gain = details["Sale Amount"] - details["Purchase Amount"]
        if details["Held for duration in years"] >= 2:
            ltcg_non_equity[asset] += gain
        else:
            stcg_other[asset] += gain

# A privately owned vehicle is a personal effect and is therefore ignored.

# Determine taxable capital gains after current and brought-forward loss set-off.
taxable = {
    "stcg_111a": max(0, stcg_111a),
    "stcg_other": {k: max(0, v) for k, v in stcg_other.items()},
    "ltcg_112a": max(0, ltcg_112a),
    "ltcg_non_equity": {k: max(0, v) for k, v in ltcg_non_equity.items()},
    "ltcg_other": max(0, ltcg_other),
