    long_term_loss,
    ltcg_non_equity_targets
    + [(taxable, "ltcg_other"), (taxable, "ltcg_112a")],
)

taxable_stcg_other = sum(taxable["stcg_other"].values())
taxable_ltcg_non_equity = sum(taxable["ltcg_non_equity"].values())
taxable_capital_gains = (
    taxable["stcg_111a"]
    + taxable_stcg_other
    + taxable["ltcg_112a"]
    + taxable_ltcg_non_equity
    + taxable["ltcg_other"]
)

other_sources = {
    "Savings Bank Interest": data["Savings Bank Interest"],
    "Deposit Interest": data["Deposit Interest"],
    "Other Interest": data["Other Interest"],
    "EPF Taxable Interest": data["EPF Taxable Interest"],
}
other_sources_total = sum(other_sources.values())
gross_total_income = net_salary + other_sources_total + taxable_capital_gains

