import json
from datetime import date

with open("input.json", "r", encoding="utf-8") as f:
    data = json.load(f)


def amount(value):
    return float(value or 0)


def parse_date(value):
    return date.fromisoformat(value)


def add_months(d, months):
    month_index = d.month - 1 + months
    year = d.year + month_index // 12
    month = month_index % 12 + 1
    leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    days = [31, 29 if leap else 28, 31, 30, 31, 30,
            31, 31, 30, 31, 30, 31]
    return date(year, month, min(d.day, days[month - 1]))


def held_over(purchase_date, sale_date, months):
    return sale_date > add_months(purchase_date, months)


def set_off(loss, gain):
    used = min(max(loss, 0.0), max(gain, 0.0))
    return gain - used, loss - used


